// Vector search only RANKS (nearest 5, best first); distance cannot decide whether the base answers a question (see raw/n8n/2026-10-01-pgvector-knowledge-base-report.md), so Gate decides.
// Gate sees all 5, numbered; Verdict returns at most 3 of them to the agent.
// The client's text goes into <question> tags: angle brackets are removed so it cannot close the tag and address the gate.
const question = String($('Trigger').first().json.question ?? '').replace(/[<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1000);
const hits = $input.all().map(i => i.json).filter(x => x && x.document);
const list = hits.map(x => `[${x.document.metadata.topic}] ${x.document.pageContent.replace(/^.*\n/, '')}`);
return [{ json: { question, list, gatePassages: list.map((p, i) => `(${i + 1}) ${p}`).join('\n\n'), count: list.length } }];

// A gate that errored emits an item with no text at all; only that case fails open (see Verdict). It must not be silent: alert the owner, at most once an hour (static data of this workflow).
const g = $('Gate').first().json;
const t = g.text ?? g.output;
const failed = typeof t !== 'string';
// truncated: the gate answered but wrote no VERDICT line (typically cut off by Max Tokens). Verdict answers NOT_FOUND for it, so this flag on the item is the countable trace of that silent bias.
const truncated = !failed && !t.split(/\r?\n/).some(l => /^\W*VERDICT\s*:\s*(YES|NO)\b/.test(l.toUpperCase().replace(/[*`_]/g, '')));
let alert = false;
if (failed) {
  const s = $getWorkflowStaticData('global');
  const now = Date.now();
  if (!s.gateAlertAt || now - s.gateAlertAt > 3600000) { s.gateAlertAt = now; alert = true; }
}
return [{ json: { failed, truncated, alert, text: '⚠️ Knowledge-base relevance check unavailable — answers are unfiltered' } }];

// Only a gate item with NO text at all (the error shape) fails open to FOUND. Any answer that is present but is not a recognisable YES means NOT_FOUND: escalation is the safe direction.
// At most 3 passages go to the agent: the ones the gate cited (so an answering passage ranked 4th or 5th is not lost), filled up with the best-ranked ones, in rank order.
const c = $('Collect').first().json;
if (!c.count) return [{ json: { verdict: 'NOT_FOUND' } }];
const pick = cited => {
  const idx = [];
  for (const n of cited) if (idx.length < 3 && !idx.includes(n)) idx.push(n);
  for (let n = 1; n <= c.count && idx.length < 3; n++) if (!idx.includes(n)) idx.push(n);
  return 'FOUND\n' + idx.sort((a, b) => a - b).map(n => c.list[n - 1]).join('\n\n');
};
const g = $('Gate').first().json;
const raw = g.text ?? g.output;
if (typeof raw !== 'string') return [{ json: { verdict: pick([]) } }];
// The gate reasons first and ends with a line VERDICT: YES <passage numbers> or VERDICT: NO. The LAST such line counts; no such line (or a NO) means NOT_FOUND.
let last = null;
for (const line of raw.split(/\r?\n/)) {
  const m = line.toUpperCase().replace(/[*`_]/g, '').match(/^\W*VERDICT\s*:\s*(YES|NO)\b(.*)$/);
  if (m) last = m;
}
if (!last || last[1] !== 'YES') return [{ json: { verdict: 'NOT_FOUND' } }];
const cited = (last[2].match(/\d+/g) || []).map(Number).filter(n => n >= 1 && n <= c.count);
return [{ json: { verdict: pick(cited) } }];
